import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    mode: 'dark',
    primary: { main: '#2563EB' },
    secondary: { main: '#0EA5E9' },
    success: { main: '#22C55E' },
    warning: { main: '#F59E0B' },
    error: { main: '#EF4444' },
    background: { default: '#0F172A', paper: '#111827' },
    text: { primary: '#F8FAFC', secondary: '#CBD5E1' },
  },
  typography: {
    fontFamily: 'Inter, Roboto, Arial, sans-serif',
    h1: { fontWeight: 700 },
    h2: { fontWeight: 700 },
    h3: { fontWeight: 700 },
    h4: { fontWeight: 700 },
    h5: { fontWeight: 600 },
    h6: { fontWeight: 600 },
  },
  shape: { borderRadius: 16 },
  components: {
    MuiCard: { styleOverrides: { root: { backgroundImage: 'linear-gradient(145deg, rgba(30,41,59,0.95), rgba(15,23,42,0.95))', boxShadow: '0 12px 35px rgba(2, 8, 23, 0.35)', border: '1px solid rgba(148,163,184,0.16)' } } },
    MuiButton: { styleOverrides: { root: { borderRadius: 999, textTransform: 'none' } } },
    MuiPaper: { styleOverrides: { root: { backgroundImage: 'linear-gradient(145deg, rgba(30,41,59,0.95), rgba(15,23,42,0.95))' } } },
  },
});

export default theme;
